/**
 * Safe feature integration registry.
 *
 * Teammates do not edit this file. They add
 * `frontend/src/features/<name>/register.tsx` with a default
 * `defineFeature({ key, component })` export; the glob below discovers it
 * lazily and registers it. Until then a typed placeholder renders the wired
 * data instead of crashing the application.
 */
import {
  Component,
  useSyncExternalStore,
  type ComponentType,
  type ErrorInfo,
  type ReactNode,
} from 'react';
import {
  AfterlifeFallback,
  AtlasFallback,
  GuidedRouteFallback,
  MarsStoriesFallback,
  MissionDebriefFallback,
  MoonStoriesFallback,
  ScienceEvidenceFallback,
} from './FeatureFallbacks';
import type {
  AfterlifeFeatureProps,
  AtlasFeatureProps,
  FeatureComponent,
  FeatureKey,
  FeaturePropsMap,
  GuidedRouteFeatureProps,
  MarsStoriesFeatureProps,
  MissionDebriefFeatureProps,
  MoonStoriesFeatureProps,
  ScienceEvidenceFeatureProps,
} from './featureTypes';

type AnyFeatureComponent = ComponentType<Record<string, never>> | ComponentType<any>;

const FEATURE_KEYS: FeatureKey[] = [
  'atlas',
  'moonStories',
  'marsStories',
  'afterlife',
  'scienceEvidence',
  'missionDebrief',
  'guidedRoute',
];

const FEATURE_META: Record<FeatureKey, { title: string; description: string }> = {
  atlas: {
    title: 'NSSDCA Archive Atlas',
    description: 'Searchable archive records, aliases, body and location confidence.',
  },
  moonStories: {
    title: 'Moon Artifact Storybook',
    description: 'Five-chapter Moon narrative with original and simplified wording.',
  },
  marsStories: {
    title: 'Mars Artifact Storybook',
    description: 'Five-chapter Mars narrative with original and simplified wording.',
  },
  afterlife: {
    title: 'Mission Timeline & Afterlife',
    description: 'Chronological events, final disposition and chapter navigation.',
  },
  scienceEvidence: {
    title: 'Science-to-Discovery Reveal + Evidence',
    description: 'Hardware-to-result reveals, claim sources and location confidence.',
  },
  missionDebrief: {
    title: 'Mission Debrief',
    description: 'Artifact quiz with server-side answer evaluation.',
  },
  guidedRoute: {
    title: 'Guided Story Route',
    description: 'Curated, ordered artifact journey with progress-ready step IDs.',
  },
};

const registry = new Map<FeatureKey, AnyFeatureComponent>();
const listeners = new Set<() => void>();
let registryVersion = 0;

function emit(): void {
  registryVersion += 1;
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function getSnapshot(): number {
  return registryVersion;
}

function isFeatureKey(value: string): value is FeatureKey {
  return (FEATURE_KEYS as string[]).includes(value);
}

export function registerFeature<K extends FeatureKey>(
  key: K,
  component: FeatureComponent<K>,
): void {
  if (!component) {
    console.warn(`[echoes] Ignoring empty feature registration for "${key}".`);
    return;
  }
  registry.set(key, component as AnyFeatureComponent);
  emit();
}

/** Test helper; safe to call at runtime when hot-reloading a feature module. */
export function unregisterFeature(key: FeatureKey): void {
  registry.delete(key);
  emit();
}

export function getRegisteredFeatures(): FeatureKey[] {
  return [...registry.keys()];
}

/* -------------------------------------------------------------------------- */
/* Optional auto-discovery                                                    */
/* -------------------------------------------------------------------------- */

const discoveryModules = import.meta.glob('../*/register.tsx') as Record<
  string,
  () => Promise<unknown>
>;

/**
 * Loads every sibling feature registration module. Each module is isolated:
 * an exception is logged and the placeholder remains in place. A module may
 * export a single default defineFeature({ key, component }) object or an
 * array of them (when one folder registers several keys).
 */
export async function discoverFeatures(): Promise<void> {
  await Promise.all(
    Object.entries(discoveryModules).map(async ([modulePath, load]) => {
      try {
        const loaded = (await load()) as { default?: unknown };
        const registrations: unknown[] = Array.isArray(loaded.default)
          ? loaded.default
          : [loaded.default];

        for (const registration of registrations) {
          const candidate = registration as
            | { key?: unknown; component?: unknown }
            | undefined;

          if (
            !candidate ||
            typeof candidate.key !== 'string' ||
            !isFeatureKey(candidate.key) ||
            !candidate.component
          ) {
            console.warn(
              `[echoes] Ignoring invalid feature registration exported by ${modulePath}. ` +
                'Expected a default defineFeature({ key, component }) or an array of them.',
            );
            continue;
          }

          registry.set(candidate.key, candidate.component as AnyFeatureComponent);
          emit();
        }
      } catch (error) {
        console.error(`[echoes] Failed to load feature module ${modulePath}:`, error);
      }
    }),
  );
}

if (typeof window !== 'undefined') {
  void discoverFeatures();
}

/* -------------------------------------------------------------------------- */
/* Error boundary and fallbacks                                               */
/* -------------------------------------------------------------------------- */

class FeatureErrorBoundary extends Component<
  { feature: FeatureKey; children: ReactNode },
  { error: Error | null }
> {
  state: { error: Error | null } = { error: null };

  static getDerivedStateFromError(error: Error): { error: Error } {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error(`[echoes] Feature "${this.props.feature}" crashed:`, error, info);
  }

  render(): ReactNode {
    if (this.state.error) {
      return (
        <div className="feature-placeholder feature-placeholder--error">
          <span className="badge badge--error">Feature error</span>
          <h3>{FEATURE_META[this.props.feature].title}</h3>
          <p>
            This feature failed to render. The rest of the application is still
            usable. Check the browser console for the component error.
          </p>
          <button
            type="button"
            className="button button--ghost"
            onClick={() => this.setState({ error: null })}
          >
            Retry feature
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

function GenericFallback({ feature }: { feature: FeatureKey }) {
  const meta = FEATURE_META[feature];
  return (
    <div className="feature-placeholder" data-feature={feature}>
      <span className="badge badge--pending">Awaiting teammate UI</span>
      <h3>{meta.title}</h3>
      <p>{meta.description}</p>
      <p className="feature-placeholder__note">
        The typed integration slot exists but no component has registered for{' '}
        <code>{feature}</code> yet.
      </p>
    </div>
  );
}

function renderFallback<K extends FeatureKey>(
  feature: K,
  props: FeaturePropsMap[K],
): ReactNode {
  switch (feature) {
    case 'atlas':
      return <AtlasFallback {...(props as AtlasFeatureProps)} />;
    case 'moonStories':
      return <MoonStoriesFallback {...(props as MoonStoriesFeatureProps)} />;
    case 'marsStories':
      return <MarsStoriesFallback {...(props as MarsStoriesFeatureProps)} />;
    case 'afterlife':
      return <AfterlifeFallback {...(props as AfterlifeFeatureProps)} />;
    case 'scienceEvidence':
      return <ScienceEvidenceFallback {...(props as ScienceEvidenceFeatureProps)} />;
    case 'missionDebrief':
      return <MissionDebriefFallback {...(props as MissionDebriefFeatureProps)} />;
    case 'guidedRoute':
      return <GuidedRouteFallback {...(props as GuidedRouteFeatureProps)} />;
    default:
      return <GenericFallback feature={feature} />;
  }
}

export interface FeatureSlotProps<K extends FeatureKey> {
  feature: K;
  props: FeaturePropsMap[K];
}

export function FeatureSlot<K extends FeatureKey>({ feature, props }: FeatureSlotProps<K>) {
  useSyncExternalStore(subscribe, getSnapshot, getSnapshot);

  const Registered = registry.get(feature) as ComponentType<FeaturePropsMap[K]> | undefined;

  if (!Registered) {
    return <>{renderFallback(feature, props)}</>;
  }

  return (
    <FeatureErrorBoundary feature={feature}>
      <Registered {...props} />
    </FeatureErrorBoundary>
  );
}

/* Typed convenience slots used by the parent application. */

export function AtlasSlot(props: AtlasFeatureProps) {
  return <FeatureSlot feature="atlas" props={props} />;
}

export function MoonStoriesSlot(props: MoonStoriesFeatureProps) {
  return <FeatureSlot feature="moonStories" props={props} />;
}

export function MarsStoriesSlot(props: MarsStoriesFeatureProps) {
  return <FeatureSlot feature="marsStories" props={props} />;
}

export function AfterlifeSlot(props: AfterlifeFeatureProps) {
  return <FeatureSlot feature="afterlife" props={props} />;
}

export function ScienceEvidenceSlot(props: ScienceEvidenceFeatureProps) {
  return <FeatureSlot feature="scienceEvidence" props={props} />;
}

export function MissionDebriefSlot(props: MissionDebriefFeatureProps) {
  return <FeatureSlot feature="missionDebrief" props={props} />;
}

export function GuidedRouteSlot(props: GuidedRouteFeatureProps) {
  return <FeatureSlot feature="guidedRoute" props={props} />;
}
